import {session,quote} from '../studio.mjs';
import {publicProducts} from '../catalog.mjs';
const json=(v,s=200)=>new Response(JSON.stringify(v),{status:s,headers:{'Content-Type':'application/json','Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff'}});
const now=()=>new Date().toISOString();
export function paymentConnections(env){const enabled=env.CHECKOUT_PAYMENTS_ENABLED==='true';return {square:enabled&&!!env.SQUARE_ACCESS_TOKEN&&!!env.SQUARE_LOCATION_ID&&!!env.SQUARE_WEBHOOK_SIGNATURE_KEY,paypal:enabled&&!!env.PAYPAL_CLIENT_ID&&!!env.PAYPAL_CLIENT_SECRET&&!!env.PAYPAL_WEBHOOK_ID};}
export function checkoutTotals(draft,env){const subtotal=draft.items.reduce((n,i)=>n+i.price.net,0),shipping=Math.round((draft.shipping?.amount||0)*100);let rates={ON:13};try{rates={...rates,...JSON.parse(env.CHECKOUT_TAX_RATES_JSON||'{}')};}catch{}const province=draft.shipping?.id==='pickup'?'ON':draft.address?.state,rate=rates[province];const ready=Number.isFinite(rate)&&rate>=0&&rate<=30;const tax=ready?Math.round((subtotal+shipping)*rate/100):null;return {subtotal,shipping,tax,rate:ready?rate:null,total:tax===null?null:subtotal+shipping+tax,currency:'CAD',taxReady:ready};}
function squareBase(env){return env.SQUARE_ENVIRONMENT==='sandbox'?'https://connect.squareupsandbox.com':'https://connect.squareup.com';}
function paypalBase(env){return env.PAYPAL_ENVIRONMENT==='sandbox'?'https://api-m.sandbox.paypal.com':'https://api-m.paypal.com';}
async function gateway(url,options){const r=await fetch(url,{...options,signal:AbortSignal.timeout(20000)});let body;try{body=await r.json();}catch{throw Error('Payment provider returned an invalid response. Retry.');}if(!r.ok)throw Error('The payment provider could not complete this step. Your order has not been marked paid.');return body;}
async function square(env,path,body){return gateway(squareBase(env)+path,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+env.SQUARE_ACCESS_TOKEN,'Content-Type':'application/json','Square-Version':'2026-09-16'},body:body?JSON.stringify(body):undefined});}
async function paypal(env,path,body,id){const token=await gateway(paypalBase(env)+'/v1/oauth2/token',{method:'POST',headers:{Authorization:'Basic '+btoa(env.PAYPAL_CLIENT_ID+':'+env.PAYPAL_CLIENT_SECRET),'Content-Type':'application/x-www-form-urlencoded'},body:'grant_type=client_credentials'});return gateway(paypalBase(env)+path,{method:body!==undefined?'POST':'GET',headers:{Authorization:'Bearer '+token.access_token,'Content-Type':'application/json','PayPal-Request-Id':id||crypto.randomUUID(),Prefer:'return=representation'},body:body!==undefined?JSON.stringify(body):undefined});}
async function orderID(s,revision,provider){const bytes=new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s.id+':'+revision)));const h=[...bytes].map(x=>x.toString(16).padStart(2,'0')).join('').slice(0,32);return [h.slice(0,8),h.slice(8,12),h.slice(12,16),h.slice(16,20),h.slice(20)].join('-');}
const complete=i=>i.designRequested||i.artworkAccepted===true;
function publicOrder(row){return {id:row.id,reference:'SG-'+row.id.slice(0,8).toUpperCase(),status:row.status,provider:row.provider,url:row.payment_url,snapshot:JSON.parse(row.snapshot),createdAt:row.created_at};}
async function verify(row,env,capture=false){if(!row.provider_order_id)return false;const snapshot=JSON.parse(row.snapshot),expected=snapshot.totals.total;
if(row.provider==='square'){const {order}=await square(env,'/v2/orders/'+encodeURIComponent(row.provider_order_id));if(!order||order.location_id!==env.SQUARE_LOCATION_ID||order.reference_id!==row.id||order.total_money?.currency!=='CAD'||Number(order.total_money.amount)!==expected)return false;const paymentIds=order.tenders?.map(t=>t.payment_id).filter(Boolean)||[];if(!paymentIds.length)return false;let paid=0;for(const id of paymentIds){const {payment}=await square(env,'/v2/payments/'+encodeURIComponent(id));if(payment?.status==='COMPLETED'&&payment.order_id===order.id&&payment.location_id===env.SQUARE_LOCATION_ID&&payment.amount_money?.currency==='CAD')paid+=Number(payment.amount_money.amount)-Number(payment.refunded_money?.amount||0);}return paid===expected;}
let order=await paypal(env,'/v2/checkout/orders/'+encodeURIComponent(row.provider_order_id));const valid=o=>o.id===row.provider_order_id&&o.purchase_units?.length===1&&o.purchase_units[0].custom_id===row.id&&o.purchase_units[0].amount?.currency_code==='CAD'&&Math.round(Number(o.purchase_units[0].amount.value)*100)===expected;if(!valid(order))return false;
if(capture&&order.status==='APPROVED'){await paypal(env,'/v2/checkout/orders/'+encodeURIComponent(row.provider_order_id)+'/capture',{},row.id+'-capture');order=await paypal(env,'/v2/checkout/orders/'+encodeURIComponent(row.provider_order_id));}if(!valid(order)||order.status!=='COMPLETED')return false;const captures=order.purchase_units[0].payments?.captures||[];return captures.length===1&&captures[0].status==='COMPLETED'&&captures[0].amount?.currency_code==='CAD'&&Math.round(Number(captures[0].amount.value)*100)===expected;}
async function markPaid(row,env){const d=JSON.parse(row.snapshot);const details={...d,paymentStatus:'paid',provider:row.provider,providerOrderId:row.provider_order_id,preflightStatus:'awaiting_production_review'};const t=now();const current=await env.DB.prepare('SELECT data FROM checkout_drafts WHERE session_id = ? AND revision = ?').bind(row.session_id,row.draft_revision).first();const draft=current?JSON.parse(current.data):null;if(draft)draft.submitted={reference:'SG-'+row.id.slice(0,8).toUpperCase(),orderId:row.id,status:'paid',at:t};const updates=[env.DB.prepare("UPDATE checkout_orders SET status = 'paid',updated_at = ? WHERE id = ? AND session_id = ?").bind(t,row.id,row.session_id),env.DB.prepare('INSERT INTO service_requests (id,type,service,name,email,phone,preferred_date,preferred_time,details,status,created_at,consent_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO NOTHING').bind(row.id,'order','Print checkout',d.address.name,d.address.email.toLowerCase(),d.address.phone||'','','',JSON.stringify(details),'pending_confirmation',t,d.consentAt)];if(draft)updates.push(env.DB.prepare('UPDATE checkout_drafts SET data = ?,revision = revision + 1,updated_at = ? WHERE session_id = ? AND revision = ?').bind(JSON.stringify(draft),t,row.session_id,row.draft_revision));await env.DB.batch(updates);return {...row,status:'paid'};}
export async function paymentRoutes(request,env,url){if(!['/api/checkout/payment','/api/checkout/order','/api/checkout/capture'].includes(url.pathname))return null;if(!env.DB)return json({error:'Checkout unavailable'},503);if(request.method==='POST'&&request.headers.get('Origin')!==url.origin)return json({error:'Invalid request origin'},403);
try{const s=await session(request,env.DB);if(!s)return json({error:'Start a secure artwork session first.'},401);const connections=paymentConnections(env);
if(url.pathname==='/api/checkout/order'||url.pathname==='/api/checkout/capture'){if(url.pathname.endsWith('/order')&&request.method!=='GET'||url.pathname.endsWith('/capture')&&request.method!=='POST')return json({error:'Method not allowed'},405);let id=url.searchParams.get('id');if(request.method==='POST'){const v=await request.json();id=v.id;}if(!/^[a-f0-9-]{36}$/.test(id||''))throw Error('Invalid order reference');let row=await env.DB.prepare('SELECT * FROM checkout_orders WHERE id = ? AND session_id = ?').bind(id,s.id).first();if(!row)return json({error:'Order not found'},404);if(row.status!=='paid'&&connections[row.provider]&&await verify(row,env,request.method==='POST'))row=await markPaid(row,env);return json({order:publicOrder(row)});}
if(request.method!=='POST')return json({error:'Use POST'},405);const text=await request.text();if(text.length>10000)throw Error('Invalid payment request');const v=JSON.parse(text);if(!connections[v.provider])return json({error:'Online payment is temporarily unavailable. Your artwork and cart are saved.'},503);if(v.consent!==true)throw Error('Accept the order terms before payment.');const draftRow=await env.DB.prepare('SELECT * FROM checkout_drafts WHERE session_id = ?').bind(s.id).first();if(!draftRow||v.revision!==draftRow.revision)return json({error:'Your cart changed. Reload checkout.'},409);const draft=JSON.parse(draftRow.data);if(draft.submitted?.status==='paid'){const paidOrder=await env.DB.prepare('SELECT * FROM checkout_orders WHERE id = ? AND session_id = ?').bind(draft.submitted.orderId,s.id).first();if(paidOrder?.status==='paid')return json({order:publicOrder(paidOrder)});throw Error('Start another checkout to place a new order.');}if(!draft.items.length||!draft.address||!draft.shipping||!draft.items.every(complete))throw Error('Confirm your artwork on the product page, then complete address and shipping.');if(draft.shipping.id!=='pickup'&&Date.now()-Date.parse(draft.shipping.selectedAt)>30*60*1000)throw Error('Refresh your delivery options before paying.');
const catalog=await publicProducts(env.DB);for(const item of draft.items){const product=catalog.find(p=>p.ruleId===item.ruleId);if(!product||product.stock===0)throw Error('An item is no longer available.');if(product.stock!==null)throw Error('This item needs inventory confirmation before online payment.');const current=await quote(env.DB,item.ruleId,item.values,item.coupon);if(current.net!==item.price.net||current.revision!==item.price.revision)throw Error('An item price changed. Return to the product and update your cart.');const fee=item.designRequested?10000:0;if(current.net<=fee)throw Error('Choose a product configuration with an available print price.');}
const totals=checkoutTotals(draft,env);if(!totals.taxReady)throw Error('Online ordering is not available for this delivery province yet.');if(totals.total<=0||totals.total>10000000)throw Error('Check the order amount');const id=await orderID(s,draftRow.revision,v.provider),snapshot={items:draft.items,address:draft.address,shipping:draft.shipping,totals,currency:'CAD',checkoutSessionId:s.id,consentAt:now(),preflightStatus:'awaiting_production_review'};
await env.DB.prepare('INSERT INTO checkout_orders (id,session_id,draft_revision,provider,status,snapshot,created_at,updated_at) SELECT ?,?,?,?,?,?,?,? WHERE EXISTS(SELECT 1 FROM checkout_drafts WHERE session_id = ? AND revision = ?) ON CONFLICT(id) DO NOTHING').bind(id,s.id,draftRow.revision,v.provider,'awaiting_payment',JSON.stringify(snapshot),now(),now(),s.id,draftRow.revision).run();let row=await env.DB.prepare('SELECT * FROM checkout_orders WHERE id = ? AND session_id = ?').bind(id,s.id).first();if(!row)return json({error:'Checkout changed. Reload.'},409);if(row.status==='paid')return json({order:publicOrder(row)});if(row.provider!==v.provider)return json({error:'A '+row.provider+' checkout is already open for this cart. Continue with that payment method.'},409);if(row.payment_url)return json({order:publicOrder(row)});
const saved=JSON.parse(row.snapshot),returnURL=url.origin+'/satin/checkout/?payment='+id;let gatewayId,paymentURL;
if(v.provider==='square'){const cents=n=>({amount:n,currency:'CAD'});const lines=saved.items.map(i=>({name:i.jobName||i.name,quantity:'1',note:`${i.values.quantity} units · ${i.spec.width} x ${i.spec.height} in`,base_price_money:cents(i.price.net)}));if(saved.totals.shipping)lines.push({name:saved.shipping.label,quantity:'1',base_price_money:cents(saved.totals.shipping)});const data=await square(env,'/v2/online-checkout/payment-links',{idempotency_key:id,order:{location_id:env.SQUARE_LOCATION_ID,reference_id:id,line_items:lines,...(saved.totals.tax?{taxes:[{uid:'sales-tax',name:saved.address.state==='ON'?'HST':'Sales tax',percentage:String(saved.totals.rate),scope:'ORDER'}]}:{})},checkout_options:{redirect_url:returnURL,allow_tipping:false,enable_coupon:false,ask_for_shipping_address:false},pre_populated_data:{buyer_email:saved.address.email},payment_note:'Satin print order '+id});const providerTotal=data.related_resources?.orders?.[0]?.total_money;if(providerTotal?.currency!=='CAD'||Number(providerTotal?.amount)!==saved.totals.total)throw Error('The payment provider total differs from your order. Please retry.');gatewayId=data.payment_link?.order_id;paymentURL=data.payment_link?.url;
}else{const a=saved.address;const data=await paypal(env,'/v2/checkout/orders',{intent:'CAPTURE',purchase_units:[{custom_id:id,invoice_id:'SG-'+id,description:'Satin print order',amount:{currency_code:'CAD',value:(saved.totals.total/100).toFixed(2)},shipping:{name:{full_name:a.name},address:{address_line_1:a.street1,...(a.street2?{address_line_2:a.street2}:{}),admin_area_2:a.city,admin_area_1:a.state,postal_code:a.zip,country_code:'CA'}}}],payment_source:{paypal:{experience_context:{brand_name:'Satin Graphic',user_action:'PAY_NOW',shipping_preference:'SET_PROVIDED_ADDRESS',return_url:returnURL,cancel_url:returnURL+'&cancelled=1'}}}},id);gatewayId=data.id;paymentURL=data.links?.find(l=>['approve','payer-action'].includes(l.rel))?.href;}
const destination=new URL(paymentURL||'https://invalid.local');const allowed=v.provider==='square'?['square.link','sandbox.square.link','checkout.square.site']:['www.paypal.com','www.sandbox.paypal.com','paypal.com','sandbox.paypal.com'];if(!gatewayId||destination.protocol!=='https:'||!allowed.includes(destination.hostname))throw Error('Payment checkout is unavailable. Retry.');await env.DB.prepare('UPDATE checkout_orders SET provider_order_id = ?,payment_url = ?,updated_at = ? WHERE id = ? AND session_id = ?').bind(gatewayId,paymentURL,now(),id,s.id).run();row={...row,provider_order_id:gatewayId,payment_url:paymentURL};return json({order:publicOrder(row)});
}catch(e){console.error('Payment checkout failed',e.message);return json({error:e.message||'Payment checkout unavailable'},400);}}

export async function paymentWebhookRoutes(request,env,url){const provider=url.pathname.match(/^\/api\/payments\/webhook\/(square|paypal)$/)?.[1];if(!provider)return null;if(request.method!=='POST')return json({error:'Use POST'},405);if(!env.DB)return json({error:'Storage unavailable'},503);
try{const raw=await request.text();if(raw.length>200000)return json({error:'Event too large'},413);let event;
if(provider==='square'){if(!env.SQUARE_WEBHOOK_SIGNATURE_KEY)return json({error:'Webhook not connected'},503);const sig=request.headers.get('x-square-hmacsha256-signature');if(!sig)return json({error:'Invalid signature'},401);let bytes;try{bytes=Uint8Array.from(atob(sig),c=>c.charCodeAt(0));}catch{return json({error:'Invalid signature'},401);}const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(env.SQUARE_WEBHOOK_SIGNATURE_KEY),{name:'HMAC',hash:'SHA-256'},false,['verify']);const notificationURL=env.SQUARE_WEBHOOK_URL||url.origin+url.pathname;if(!await crypto.subtle.verify('HMAC',key,bytes,new TextEncoder().encode(notificationURL+raw)))return json({error:'Invalid signature'},401);event=JSON.parse(raw);
}else{if(!env.PAYPAL_WEBHOOK_ID||!env.PAYPAL_CLIENT_ID||!env.PAYPAL_CLIENT_SECRET)return json({error:'Webhook not connected'},503);const h=request.headers;const names=['paypal-auth-algo','paypal-cert-url','paypal-transmission-id','paypal-transmission-sig','paypal-transmission-time'];if(names.some(k=>!h.get(k)||h.get(k).length>2000))return json({error:'Invalid signature'},401);event=JSON.parse(raw);const verified=await paypal(env,'/v1/notifications/verify-webhook-signature',{auth_algo:h.get(names[0]),cert_url:h.get(names[1]),transmission_id:h.get(names[2]),transmission_sig:h.get(names[3]),transmission_time:h.get(names[4]),webhook_id:env.PAYPAL_WEBHOOK_ID,webhook_event:event});if(verified.verification_status!=='SUCCESS')return json({error:'Invalid signature'},401);}
const providerID=provider==='square'?(event.data?.object?.payment?.order_id||event.data?.object?.order?.id):(event.resource?.supplementary_data?.related_ids?.order_id||(/^CHECKOUT.ORDER\./.test(event.event_type||'')?event.resource?.id:null));if(!providerID)return json({received:true});const rows=await env.DB.prepare('SELECT * FROM checkout_orders WHERE provider = ? AND provider_order_id = ?').bind(provider,providerID).all();for(const row of rows.results){if(await verify(row,env,false))await markPaid(row,env);}return json({received:true});
}catch(e){console.error('Payment webhook failed',e.message);return json({error:'Webhook processing unavailable. Retry.'},503);}}
